def count_odd_sum_subsequences(nums):
    modulo=10**9+7;even=odd=0
    for number in nums:
        if number%2:even,odd=(even+odd)%modulo,(odd+even+1)%modulo
        else:even,odd=(2*even+1)%modulo,(2*odd)%modulo
    return odd

